versions_bump() {
  local typ="${1:-patch}"  # major, minor, patch
  local version=$(cat VERSION)
  IFS="." read -ra teile <<< "$version"

  case "$typ" in
    major) (( teile[0]++ )); teile[1]=0; teile[2]=0 ;;
    minor) (( teile[1]++ )); teile[2]=0 ;;
    patch) (( teile[2]++ )) ;;
  esac

  echo "${teile[0]}.${teile[1]}.${teile[2]}" > VERSION
}

